3	// ptrUint is a helper function to create a pointer to uint.
4	func ptrUint(v uint) *uint {
5		return &v
6	}
7	
8	// ApplyDefaults applies default values to the configuration.
9	func (cfg *Config) ApplyDefaults() {
10		// Apply defaults for global consumer config
11		if cfg.ConsumersConfig.DefaultMaxRetries == nil {
12			cfg.ConsumersConfig.DefaultMaxRetries = ptrUint(defaultMaxRetries)
13		}
14		if cfg.ConsumersConfig.DefaultInitialBackoff == 0 {
15			cfg.ConsumersConfig.DefaultInitialBackoff = defaultInitialBackoff
16		}
17		if cfg.ConsumersConfig.DefaultMaxBackoff == 0 {
18			cfg.ConsumersConfig.DefaultMaxBackoff = defaultMaxBackoff
19		}
20		if cfg.ConsumersConfig.DefaultProcessingTimeout == 0 {
21			cfg.ConsumersConfig.DefaultProcessingTimeout = defaultProcessingTimeout
22		}
23		if cfg.ConsumersConfig.DefaultChannelBufferSize == 0 {
24			cfg.ConsumersConfig.DefaultChannelBufferSize = defaultChannelBufferSize
25		}
26		if cfg.ConsumersConfig.DefaultMaxPollRecords == 0 {
27			cfg.ConsumersConfig.DefaultMaxPollRecords = defaultMaxPollRecords
28		}
29	
30		// Apply defaults from global consumer config to individual consumers
31		for i := range cfg.ConsumersConfig.ConsumerConfig {
32			applyConsumerDefaults(&cfg.ConsumersConfig.ConsumerConfig[i], &cfg.ConsumersConfig)
33		}
34	
35		// Apply default producer config settings
36		if cfg.ProducerConfig.ReadinessTimeoutSeconds == 0 {
37			cfg.ProducerConfig.ReadinessTimeoutSeconds = defaultProducerReadinessTimeout
38		}
39		if cfg.ProducerConfig.Linger == 0 {
40			cfg.ProducerConfig.Linger = defaultProducerLinger
41		}
42		if cfg.ProducerConfig.Compression == "" {
43			cfg.ProducerConfig.Compression = defaultProducerCompression
44		}
45		if cfg.ProducerConfig.DeliveryTimeout == 0 {
46			cfg.ProducerConfig.DeliveryTimeout = defaultProducerDeliveryTimeout
47		}
48		if cfg.ProducerConfig.MaxBufferedRecords == 0 {
49			cfg.ProducerConfig.MaxBufferedRecords = defaultProducerMaxBufferedRecords
50		}
51	}
52	
53	// applyConsumerDefaults applies defaults to an individual consumer configuration.
54	func applyConsumerDefaults(consumer *ConsumerConfig, globalConfig *ConsumersConfig) {
55		if consumer.GroupID == "" {
56			consumer.GroupID = globalConfig.DefaultGroupID
57		}
58		if consumer.AutoOffsetReset == "" {
59			consumer.AutoOffsetReset = globalConfig.DefaultAutoOffsetReset
60		}
61		// Apply default DLQ topic naming convention: {topic}.dlq
62		if consumer.EnableDLQ && consumer.DLQTopic == "" {
63			consumer.DLQTopic = consumer.Topic + ".dlq"
